const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Winnipeg geometry
  const lakeWinnipeg = ee.Geometry.Polygon([
    [[-99.5, 50.0], [-96.5, 50.0], [-96.5, 54.5], [-99.5, 54.5], [-99.5, 50.0]]
  ]);

  // 2. Cloud masking function for Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Function to calculate ice extent using NDSI threshold
  function calculateIceExtent(date, geometry) {
    const startDate = date;
    const endDate = ee.Date(date).advance(1, 'day');

    let col = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

    const size = col.size().getInfo();

    if (size === 0) {
      return null;
    }

    const image = col.map(maskClouds).median();

    // Calculate NDSI: (Green - SWIR) / (Green + SWIR)
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('ndsi');

    // Ice typically has NDSI > 0.4
    const iceMask = ndsi.gt(0.4);

    // Count ice pixels
    const iceStats = iceMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e9
    });

    const icePixels = iceStats.get('ndsi').getInfo();

    // Count valid pixels (for detecting C2 case)
    const validStats = iceMask.mask(iceMask.gte(0)).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e9
    });

    const validPixels = validStats.get('ndsi').getInfo();

    return {
      icePixels: icePixels,
      validPixels: validPixels,
      imageCount: size
    };
  }

  // 4. Calculate ice extent for both dates
  console.log("Analyzing Lake Winnipeg ice extent...");

  const may7Results = calculateIceExtent('2021-05-07', lakeWinnipeg);

  if (may7Results === null) {
    console.log("No images found for May 7, 2021");
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`May 7: Images=${may7Results.imageCount}, Valid=${may7Results.validPixels}, Ice=${may7Results.icePixels}`);

  const may19Results = calculateIceExtent('2021-05-19', lakeWinnipeg);

  if (may19Results === null) {
    console.log("No images found for May 19, 2021");
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`May 19: Images=${may19Results.imageCount}, Valid=${may19Results.validPixels}, Ice=${may19Results.icePixels}`);

  // 5. Check for C2 case (no valid pixels)
  if (may7Results.validPixels === 0 || may19Results.validPixels === 0) {
    console.log("No valid pixels after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Check for C3 case (invalid calculation)
  if (may7Results.icePixels === null || may19Results.icePixels === null ||
      isNaN(may7Results.icePixels) || isNaN(may19Results.icePixels)) {
    console.log("Calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare ice extents
  const iceDecrease = may19Results.icePixels < may7Results.icePixels;
  const percentChange = ((may19Results.icePixels - may7Results.icePixels) / may7Results.icePixels * 100).toFixed(1);

  console.log(`Ice change: ${percentChange}%`);

  if (iceDecrease) {
    console.log("Ice extent decreased between the two dates");
    console.log("<answer>A</answer>");
  } else {
    console.log("Ice extent did not decrease");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
